#include <stdio.h>

struct Contact {
    char name[30];
    char phone[15];
};

int main() {
    struct Contact contacts[2] = {
        {"Asha", "9876543210"},
        {"Ravi", "9123456780"}
    };

    FILE *fp = fopen("contacts.txt", "w");
    for (int i = 0; i < 2; i++) {
        fprintf(fp, "%s,%s\n", contacts[i].name, contacts[i].phone);
    }
    fclose(fp);

    fp = fopen("contacts.txt", "r");
    char line[50];
    printf("Saved contacts:\n");
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("%s", line);
    }
    fclose(fp);

    return 0;
}
